params.command:
$ErrorActionPreference='Continue'
$relay=Join-Path $env:USERPROFILE 'HeavenBridgeRepo'
$tmp=Join-Path $env:USERPROFILE 'mhw-patcheq-clean'
if (Test-Path $tmp) { Remove-Item -Recurse -Force $tmp }
$url=(git -C $relay remote get-url origin).Trim()
git clone --no-local $relay $tmp *> $null
git -C $tmp remote set-url origin $url
$deleted=@(); $failed=@(); $kept=@()
for($pass=1; $pass -le 3; $pass++){
  git -C $tmp fetch origin '+refs/heads/*:refs/remotes/origin/*' --prune *> $null
  $branches=git -C $tmp for-each-ref --format='%(refname:short)' refs/remotes/origin | Where-Object { $_ -ne 'origin' -and $_ -ne 'origin/HEAD' }
  $changed=$false
  foreach($rb in $branches){
    $b=$rb -replace '^origin/',''
    if($b -in @('main','heaven-bridge')) { continue }
    $before=(git -C $tmp rev-parse "origin/$b" 2>$null).Trim()
    if($LASTEXITCODE -ne 0){ continue }
    $cherry=@(git -C $tmp cherry origin/main "origin/$b" 2>$null)
    if($LASTEXITCODE -ne 0){ $failed += [pscustomobject]@{branch=$b;reason='git-cherry-failed'}; continue }
    $plus=@($cherry | Where-Object { $_ -like '+ *' })
    if($plus.Count -eq 0){
      git -C $tmp fetch origin main "$b" --prune *> $null
      $after=(git -C $tmp rev-parse "origin/$b" 2>$null).Trim()
      if($LASTEXITCODE -ne 0 -or $after -ne $before){ continue }
      $cherry2=@(git -C $tmp cherry origin/main "origin/$b" 2>$null)
      if($LASTEXITCODE -eq 0 -and @($cherry2 | Where-Object { $_ -like '+ *' }).Count -eq 0){
        git -C $tmp push origin ":refs/heads/$b" *> $null
        if($LASTEXITCODE -eq 0){ $deleted += $b; $changed=$true }
        else { $failed += [pscustomobject]@{branch=$b;reason='delete-failed'} }
      }
    }
  }
  if(-not $changed){ break }
}
git -C $tmp fetch origin '+refs/heads/*:refs/remotes/origin/*' --prune *> $null
$branches=git -C $tmp for-each-ref --format='%(refname:short)' refs/remotes/origin | Where-Object { $_ -ne 'origin' -and $_ -ne 'origin/HEAD' }
foreach($rb in $branches){
  $b=$rb -replace '^origin/',''
  if($b -in @('main','heaven-bridge')) { continue }
  $cherry=@(git -C $tmp cherry origin/main "origin/$b" 2>$null)
  $plus=@($cherry | Where-Object { $_ -like '+ *' })
  $kept += [pscustomobject]@{branch=$b;unique_patches=$plus.Count}
}
[pscustomobject]@{deleted=$deleted;deleted_count=$deleted.Count;remaining=$kept;remaining_count=$kept.Count;failed=$failed;failed_count=$failed.Count;main=(git -C $tmp rev-parse origin/main).Trim()} | ConvertTo-Json -Depth 6 -Compress
